command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9051e174da20264f31968e91ddb40289ace10149"
$candidate="4e59a22c742c7fa8d5d0e21e221f01ff8151e2be"
$work="work/f5-f6-main-reapply-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-f5f6-"+$env:GITHUB_RUN_ID)
$cache=Join-Path $repo "logs\f5-f6-runtime-4e59a22c"
$range=$main+"..."+$candidate
Set-Location -LiteralPath $repo
& git fetch origin main $work --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
if($mainSha -ne $main){throw "main moved before validation: $mainSha"}
$candidateSha=(& git rev-parse ("refs/remotes/origin/"+$work)).Trim()
if($candidateSha -ne $candidate){throw "candidate branch moved before validation: $candidateSha"}
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "candidate temp worktree creation failed"}
try {
  Set-Location -LiteralPath $temp
  & git diff --check $range
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}
  & cmd /c "build.bat Release"
  if($LASTEXITCODE -ne 0){throw "Release build failed"}
  if(Test-Path -LiteralPath $cache){Remove-Item -LiteralPath $cache -Recurse -Force}
  New-Item -ItemType Directory -Force -Path $cache | Out-Null
  Copy-Item -LiteralPath (Join-Path $temp "out\winui\Release\*") -Destination $cache -Recurse -Force
  Write-Host ("F5_F6_RUNTIME_CACHE="+$cache)
  $env:FLY_MIGRATION_CONFIGURATION="Release"
  & python -X utf8 tests/winui/test_shortcut_gui.py
  if($LASTEXITCODE -ne 0){throw "focused F5/F6 GUI acceptance failed"}
  Write-Host "F5_F6_MAIN_REAPPLY_ACCEPTANCE=PASS"
} finally {
  Remove-Item Env:FLY_MIGRATION_CONFIGURATION -ErrorAction SilentlyContinue
  Set-Location -LiteralPath $repo
  & git worktree remove --force $temp
  if($LASTEXITCODE -ne 0){throw "candidate temp worktree cleanup failed"}
}
